<?php
require_once __DIR__.'/../api-auth.php';require_once __DIR__.'/../../../config/config.php';require_once __DIR__.'/../../../includes/student-communication-api.php';
$student=requireApiStudent($pdo);$userId=(int)$student['user_id'];$studentId=(int)$student['student_id'];$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
try{
 if($method==='GET'){$from=studentApiDate((string)($_GET['from']??''));$to=studentApiDate((string)($_GET['to']??''));$sql="SELECT ev.identifiant_public uuid,ev.titre title,ev.description,ev.type_evenement type,ev.debut starts_at,ev.fin ends_at,ev.lieu location,ev.lien_externe external_url,ev.statut status,ev.cree_par_utilisateur_id creator_user_id,p.statut_reponse response_status,p.repondu_le responded_at,rv.fournisseur meeting_provider,rv.code_acces meeting_code FROM evenements_calendrier ev JOIN participants_evenements p ON p.evenement_calendrier_id=ev.id LEFT JOIN reunions_visioconference rv ON rv.evenement_calendrier_id=ev.id WHERE p.utilisateur_id=:user";$params=['user'=>$userId];if($from){$sql.=' AND ev.fin>=:from';$params['from']=$from->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}else $sql.=' AND ev.fin>=UTC_TIMESTAMP()-INTERVAL 30 DAY';if($to){$sql.=' AND ev.debut<=:to';$params['to']=$to->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}$sql.=" AND ev.statut<>'annule' ORDER BY ev.debut";$q=$pdo->prepare($sql);$q->execute($params);apiResponse(true,'',['items'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}
 if($method==='POST'){$input=apiInput();$title=trim((string)($input['title']??''));$start=studentApiDate((string)($input['starts_at']??''));$end=studentApiDate((string)($input['ends_at']??''));$recipients=studentCommunicationResolveRecipients($pdo,$userId,$studentId,is_array($input['participant_user_ids']??null)?$input['participant_user_ids']:[]);if($title===''||mb_strlen($title)>255||!$start||!$end||$end<$start||!$recipients)apiResponse(false,'Evenement ou participants invalides.',[],422);$type=(string)($input['type']??'reunion');if(!in_array($type,['reunion','convocation','visite','evaluation','echeance','autre'],true))$type='reunion';$uuid=communicationUlid();$org=studentCommunicationOrganisation($pdo,$studentId);$pdo->beginTransaction();$pdo->prepare('INSERT INTO evenements_calendrier(identifiant_public,organisation_id,titre,description,type_evenement,debut,fin,lieu,lien_externe,cree_par_utilisateur_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$uuid,$org,$title,trim((string)($input['description']??''))?:null,$type,$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),$end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),mb_substr(trim((string)($input['location']??'')),0,255)?:null,null,$userId]);$eventId=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO participants_evenements(evenement_calendrier_id,utilisateur_id,statut_reponse,repondu_le) VALUES(?,?,?,?)');$q->execute([$eventId,$userId,'accepte',gmdate('Y-m-d H:i:s')]);foreach($recipients as $recipient){$q->execute([$eventId,$recipient,'invite',null]);communicationNotifier($pdo,$recipient,$org,'invitation_calendrier','Nouvel evenement',$title,rtrim(BASE_URL,'/').'/api/v1/student/calendar',['event_uuid'=>$uuid,'action'=>['type'=>'calendar_event','target_id'=>$uuid,'label'=>"Voir l'evenement",'title'=>$title,'metadata'=>[]]]);}$pdo->commit();apiResponse(true,'Evenement cree.',['event'=>['uuid'=>$uuid,'participant_count'=>count($recipients)+1]],201);}
 header('Allow: GET, POST');apiResponse(false,'Methode HTTP non autorisee.',[],405);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[API CALENDAR] '.$e->getMessage());apiResponse(false,'Impossible de gerer le calendrier.',[],500);}
